using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ReviewLioraExpressionShading {
 const string Output="Data/Liora/ShadingRepair/Previews/";
 static BinaryReader original;static JToken[] ranges;static int scopedCount;
 static Vector3 Read()=>new Vector3(original.ReadSingle(),original.ReadSingle(),original.ReadSingle());
 static void Restore(int shape,Vector3[] n,Vector3[] t){original.BaseStream.Position=8L+shape*scopedCount*24L;foreach(var section in ranges)for(int j=(int)section["offset"];j<(int)section["offset"]+(int)section["vertices"];j++){n[j]=Read();t[j]=Read();}}
 static Mesh Snapshot(SkinnedMeshRenderer r,Transform root,bool before){
 var source=r.sharedMesh;var p=source.vertices;var n=source.normals;var t=source.tangents;var dp=new Vector3[p.Length];var dn=new Vector3[p.Length];var dt=new Vector3[p.Length];
 for(int s=0;s<source.blendShapeCount;s++){float w=r.GetBlendShapeWeight(s)*.01f;if(w==0)continue;source.GetBlendShapeFrameVertices(s,0,dp,dn,dt);if(before)Restore(s,dn,dt);for(int j=0;j<p.Length;j++){p[j]+=dp[j]*w;n[j]+=dn[j]*w;t[j]+=new Vector4(dt[j].x,dt[j].y,dt[j].z,0)*w;}}
 var matrices=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*source.bindposes[j]).ToArray();var normalMatrices=matrices.Select(m=>m.inverse.transpose).ToArray();var op=new Vector3[p.Length];var on=new Vector3[p.Length];var ot=new Vector4[p.Length];
 using(var counts=source.GetBonesPerVertex())using(var weights=source.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++){Vector3 tangent=Vector3.zero;for(int k=0;k<counts[j];k++){var w=weights[at++];op[j]+=matrices[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;on[j]+=normalMatrices[w.boneIndex].MultiplyVector(n[j])*w.weight;tangent+=matrices[w.boneIndex].MultiplyVector(t[j])*w.weight;}on[j].Normalize();tangent.Normalize();ot[j]=new Vector4(tangent.x,tangent.y,tangent.z,t[j].w);}}
 var m=new Mesh{name="Evaluated shading review",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};m.vertices=op;m.normals=on;m.tangents=ot;m.uv=source.uv;m.subMeshCount=source.subMeshCount;for(int j=0;j<source.subMeshCount;j++)m.SetTriangles(source.GetTriangles(j),j);m.RecalculateBounds();return m;
 }
 static Dictionary<string,float> Pose(string name){
 switch(name){case "BlinkLeft":return new Dictionary<string,float>{{"eyeBlinkLeft",100}};case "BlinkRight":return new Dictionary<string,float>{{"eyeBlinkRight",100}};case "BlinkBoth":return new Dictionary<string,float>{{"eyeBlinkLeft",100},{"eyeBlinkRight",100}};case "BrowRaised":return new Dictionary<string,float>{{"browInnerUp",100},{"browOuterUpLeft",100},{"browOuterUpRight",100}};
 case "MixedSpeech":return new Dictionary<string,float>{{"viseme_FF",70},{"emo_joy",25}};case "MixedBlinkSmile":return new Dictionary<string,float>{{"eyeBlinkLeft",65},{"eyeBlinkRight",65},{"emo_joy",40}};
 case "Neutral":return new Dictionary<string,float>();}
 if(name.StartsWith("Viseme"))return new Dictionary<string,float>{{"viseme_"+name.Substring(6),100}};
 return new Dictionary<string,float>{{"emo_"+name.ToLowerInvariant(),100}};
 }
 public static object Run(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");Directory.CreateDirectory(Output);var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");var scene=EditorSceneManager.NewPreviewScene();original=new BinaryReader(File.OpenRead("Data/Liora/ShadingRepair/original_scoped_shading.bin"));original.ReadInt32();scopedCount=original.ReadInt32();ranges=JObject.Parse(File.ReadAllText("Data/Liora/HierarchyRepair/sections.json"))["sections"].Where(s=>((string)s["name"]).StartsWith("BAKED_head_lod0_mesh")).ToArray();
 try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var cameraGo=new GameObject("Matched shading review camera");SceneManager.MoveGameObjectToScene(cameraGo,scene);var camera=cameraGo.AddComponent<Camera>();camera.scene=scene;camera.cameraType=CameraType.Preview;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.13f,.15f,.18f);camera.orthographic=true;camera.orthographicSize=.16f;camera.nearClipPlane=.01f;camera.farClipPlane=10;camera.transform.position=new Vector3(0,1.61f,3);camera.transform.LookAt(new Vector3(0,1.61f,0));
 foreach(var pair in new[]{(rotation:new Vector3(25,155,0),intensity:1.5f),(rotation:new Vector3(-15,215,0),intensity:.8f)}){var go=new GameObject("Review light");SceneManager.MoveGameObjectToScene(go,scene);var l=go.AddComponent<Light>();l.type=LightType.Directional;l.intensity=pair.intensity;l.shadows=LightShadows.None;l.cullingMask=1<<30;go.transform.rotation=Quaternion.Euler(pair.rotation);}
 var files=new List<string>();foreach(string pose in new[]{"Neutral","BlinkLeft","BlinkRight","BlinkBoth","BrowRaised","Joy","Anger","Surprise","Fear","Disgust","Sadness","VisemeFF","VisemePP","Visemeaa","VisemeTH","MixedSpeech","MixedBlinkSmile"}){
 for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);foreach(var pair in Pose(pose)){int index=face.sharedMesh.GetBlendShapeIndex(pair.Key);if(index<0)throw new Exception("Unknown shape "+pair.Key);face.SetBlendShapeWeight(index,pair.Value);}
 foreach(bool before in new[]{true,false}){var mesh=Snapshot(face,root.transform,before);var go=new GameObject("Explicitly evaluated face");SceneManager.MoveGameObjectToScene(go,scene);go.layer=30;go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterials=face.sharedMaterials;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;
 try{var rt=RenderTexture.GetTemporary(640,720,24);var previous=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(640,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,640,720),0,0);tex.Apply();string file=Output+pose+"_"+(before?"Before":"After")+".png";File.WriteAllBytes(file,tex.EncodeToPNG());files.Add(file);UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=null;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}}finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(mesh);}
 }}var report=new{files,poses=17,matchedCameraLightMaterialsAndGeometry=true,currentSavedMeshEvaluatedExplicitly=true,sourceOriginalShadingUsedForBefore=true,scalpSimulationNotRendered=true,sceneSaved=false,playModeTested=false};File.WriteAllText("Data/Liora/ShadingRepair/render_review.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{images=files.Count};
 }finally{original.Dispose();PrefabUtility.UnloadPrefabContents(root);EditorSceneManager.ClosePreviewScene(scene);}
 }
}
